import { h, createApp } from 'vue';
import { findOrginCompInfo } from '../LayoutAttr/ComponentInfo';
import { findOrginEvents } from '../LayoutAttr/EventInfo';
import { findOrginMethods } from '../LayoutAttr/MethodInfo';
import { findOrginProps } from '../LayoutAttr/PropertyInfo';
import ElementPlus from 'element-plus';
export function designDrawDomVirtual(vueComp, isDesigning, vueProps) {
    var fragment = window.document.createDocumentFragment();
    // let divdom = window.document.createElement('div')
    // fragment.appendChild(divdom)
    var allprops = findOrginProps(vueComp);
    var methods = findOrginMethods(vueComp);
    var events = findOrginEvents(vueComp);
    var compInfo = findOrginCompInfo(vueComp);
    if (!vueProps) {
        vueProps = {};
    }
    vueProps.designerMethods = methods;
    vueProps.properties = allprops;
    vueProps.designerEvents = events;
    vueProps.compInfo = compInfo;
    vueProps.isDesigning = isDesigning;
    var comp = h(vueComp, vueProps);
    var app = createApp({ render: function () { return comp; } });
    app.use(ElementPlus);
    app.mount(fragment);
    comp.component.proxy.renderContainer = fragment;
    return { virtualDom: fragment, vueComp: comp.component.proxy };
}
export function designDrawDomReal(dom, vueComp, isDesigning, vueProps) {
    // let divdom = window.document.createElement('div')
    // fragment.appendChild(divdom)
    var allprops = findOrginProps(vueComp);
    var methods = findOrginMethods(vueComp);
    var events = findOrginEvents(vueComp);
    var compInfo = findOrginCompInfo(vueComp);
    if (!vueProps) {
        vueProps = {};
    }
    vueProps.designerMethods = methods;
    vueProps.properties = allprops;
    vueProps.designerEvents = events;
    vueProps.compInfo = compInfo;
    vueProps.isDesigning = isDesigning;
    var comp = h(vueComp, vueProps);
    var app = createApp({ render: function () { return comp; } });
    app.use(ElementPlus);
    app.mount(dom);
    comp.component.proxy.renderContainer = dom;
    return comp.component.proxy;
}
