export function DMethodAttr(info) {
    return function (target, methodField, detail) {
        info.methodField = methodField;
        var targetCons = target.constructor;
        var findCache = window.$designany_allDMethodCache.find(function (o) { return o.target === targetCons; });
        if (!findCache) {
            ;
            window.$designany_allDMethodCache.push({ target: targetCons, info: [] });
            findCache = window.$designany_allDMethodCache.find(function (o) { return o.target === targetCons; });
        }
        // **************************************
        var findProp = findCache.info.find(function (o) { return o.methodField === methodField; });
        if (!findProp) {
            var newperperty = deepClone(info);
            findCache.info.push(newperperty);
        }
    };
}
export function findOrginMethods(enginLayout) {
    if (enginLayout.lyl_orginMethods && enginLayout.lyl_orginMethods.length > 0) {
        return enginLayout.lyl_orginMethods;
    }
    var resMethods = [];
    for (var index = 0; index < window.$designany_allDMethodCache.length; index++) {
        var oneDPropCache = window.$designany_allDMethodCache[index];
        if (enginLayout == oneDPropCache.target || enginLayout.prototype instanceof oneDPropCache.target || enginLayout.prototype == oneDPropCache.target) {
            resMethods = oneDPropCache.info.concat(resMethods);
        }
    }
    enginLayout.lyl_orginMethods = deepClone(resMethods);
    return enginLayout.lyl_orginMethods;
}
